BEGIN;
UPDATE workflow_entity
SET nodes=$WF10N$[{"parameters":{"httpMethod":"POST","path":"send-recording","responseMode":"responseNode","options":{}},"id":"5857db6a-c306-44fe-8e59-ef4d40a7250b","name":"Webhook","type":"n8n-nodes-base.webhook","typeVersion":2,"position":[20192,2160],"webhookId":"send-recording"},{"parameters":{"jsCode":"// Literal SQL seguro para el nodo MySQL de n8n (sin saltos de línea, sin \"$\", sin \"{{\").\nfunction q(v) {\n  if (v === null || v === undefined) return 'NULL';\n  if (typeof v === 'number') return Number.isFinite(v) ? String(Math.trunc(v)) : 'NULL';\n  return \"'\" + String(v).replace(/\\u0000/g, '').replace(/[\\r\\n]+/g, ' ').replace(/\\$/g, '')\n    .replace(/\\\\/g, '\\\\\\\\').replace(/'/g, \"''\").replace(/\\{\\{/g, '{ {').replace(/\\}\\}/g, '} }') + \"'\";\n}\n// \"followup_id|lead_id|synced|created_epoch|call_status|outcome\" -> objeto\nfunction parseOwner(s) {\n  if (!s) return null;\n  const p = String(s).split('|');\n  if (p.length < 4 || !p[0]) return null;\n  return { followup_id: p[0], lead_id: p[1] || null, synced: Number(p[2]) === 1 ? 1 : 0, created_epoch: Number(p[3]) || null, call_status: p[4] || null, outcome: p[5] || null };\n}\n// Duración desde el header WAV (sólo informativo: CRM no filtra por duración)\nfunction wavSecs(buf) {\n  try {\n    if (buf.length < 44 || buf.toString('ascii', 0, 4) !== 'RIFF') return null;\n    const byteRate = buf.readUInt32LE(28);\n    if (!byteRate) return null;\n    return Math.round(Math.max(0, buf.length - 44) / byteRate);\n  } catch (e) { return null; }\n}\nfunction countryOf(digits) {\n  if (digits.startsWith('977')) return 'nepal';\n  if (digits.startsWith('91')) return 'india';\n  if (digits.startsWith('58')) return 'venezuela';\n  if (digits.startsWith('52')) return 'mexico';\n  if (digits.startsWith('57')) return 'colombia';\n  return 'unknown';\n}\n// Condición común: filas válidas de wf_call_followups (excluye las históricas 'undefined')\n// (sin el carácter dólar: dentro del nodo MySQL, n8n arma la query con String.replace y un dólar seguido de\n// comilla se interpreta como patrón de reemplazo, corrompiendo el SQL)\nconst FCF_OK = \"CHAR_LENGTH(f.followup_id) = 36 AND f.followup_id REGEXP '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}' AND f.phone <> 'undefined' AND f.lead_id <> 'undefined'\";\n// Si el nodo MySQL anterior devolvió un error como item, se corta la ejecución (nunca se sigue \"a ciegas\")\nfunction assertNoDbError(items, where) {\n  const bad = items.filter(i => i && i.json && (i.json.error || (i.json.message && i.json.filename === undefined && i.json.owner === undefined)));\n  if (bad.length) throw new Error('Error de MySQL en ' + where + ': ' + String(bad[0].json.message || JSON.stringify(bad[0].json.error)).slice(0, 300));\n}\n\n// ============================================================================\n// Convert Base64 to Binary (Asterisk) — 1 request = 1 grabación (wf10-worker.py)\n// Valida el audio, calcula duración (sólo para Telegram) y arma la búsqueda del\n// DUEÑO de la grabación en wf_call_followups:\n//   dueño = la PRIMERA fila provider='asterisk' del mismo teléfono creada desde\n//   el inicio de la llamada (UNIQUEID = epoch de inicio del canal) y hasta 30 min\n//   después. WF2 escribe esa fila apenas termina el dial de ESA llamada; la\n//   siguiente llamada al mismo lead ocurre horas después (ciclo 3x3).\n// ============================================================================\nconst item = $input.first().json;\nconst body = item.body || item;\n\nconst base64 = String(body.audio_base64 || '');\nconst buffer = Buffer.from(base64, 'base64');\nconst phoneDigits = String(body.phone || '').replace(/[^0-9]/g, '');\nconst country = countryOf(phoneDigits);\nconst secs = wavSecs(buffer);\nconst validAudio = buffer.length > 44 && buffer.toString('ascii', 0, 4) === 'RIFF';\n\n// UNIQUEID de Asterisk: \"<epoch>.<secuencia>\" (o \"<systemname>-<epoch>.<secuencia>\")\nconst uidSrc = [body.uniqueid, body.unique_id, body.uid, body.filename, body.wav].filter(Boolean).map(String).join(' ');\nconst m = uidSrc.match(/(\\d{9,11})\\.(\\d+)/);\nconst callEpoch = m ? Number(m[1]) : null;\nconst uniqueid = m ? m[1] + '.' + m[2] : null;\nconst p10 = phoneDigits.slice(-10);\n\nlet lookup_sql;\nlet match_mode;\nif (callEpoch) {\n  match_mode = 'owner_by_call_start';\n  lookup_sql = \"SELECT r.p10, (SELECT CONCAT_WS('|', f.followup_id, f.lead_id, COALESCE(f.recording_synced,0), UNIX_TIMESTAMP(f.created_at), COALESCE(f.call_status,''), COALESCE(f.outcome,'')) \" +\n    \"FROM wf_call_followups f WHERE f.provider = 'asterisk' AND \" + FCF_OK + \" AND RIGHT(f.phone,10) = r.p10 \" +\n    \"AND f.created_at >= FROM_UNIXTIME(r.t_s - 120) AND f.created_at <= FROM_UNIXTIME(r.t_s + 1800) \" +\n    \"ORDER BY f.created_at ASC, f.id ASC LIMIT 1) AS owner FROM (SELECT \" + q(p10) + \" AS p10, \" + q(callEpoch) + \" AS t_s) r\";\n} else {\n  // Sin UNIQUEID en el payload (p. ej. el cron viejo manda \"<tel>_<fecha>.wav\"): no se conoce la hora\n  // exacta de la llamada. Se acota a filas del mismo teléfono creadas desde (ahora - duración - 30 min):\n  // con el ciclo 3x3 (>= 2 h entre intentos al mismo número) ahí hay una sola llamada. Se prefiere la\n  // pendiente; si sólo hay una ya sincronizada (reenvío de algo ya subido) -> not_pending, sin PUT.\n  // Una grabación que llega más tarde que eso no se asigna (503): mejor esperar que adjuntar mal.\n  match_mode = 'fallback_time_bracket';\n  const bracket = Math.max(0, Math.round(secs || 0)) + 1800;\n  lookup_sql = \"SELECT r.p10, (SELECT CONCAT_WS('|', f.followup_id, f.lead_id, COALESCE(f.recording_synced,0), UNIX_TIMESTAMP(f.created_at), COALESCE(f.call_status,''), COALESCE(f.outcome,'')) \" +\n    \"FROM wf_call_followups f WHERE f.provider = 'asterisk' AND \" + FCF_OK + \" AND RIGHT(f.phone,10) = r.p10 \" +\n    \"AND f.created_at >= NOW() - INTERVAL \" + q(bracket) + \" SECOND AND f.created_at <= NOW() + INTERVAL 60 SECOND \" +\n    \"AND (COALESCE(f.recording_synced,0) = 0 OR UPPER(COALESCE(f.outcome,'')) = 'CONNECTED') \" +\n    \"ORDER BY COALESCE(f.recording_synced,0) ASC, f.created_at ASC, f.id ASC LIMIT 1) AS owner FROM (SELECT \" + q(p10) + \" AS p10) r\";\n}\n\nconsole.log(`📥 WF10 Asterisk | phone=${phoneDigits} uid=${uniqueid} bytes=${buffer.length} secs=${secs} valid=${validAudio} match=${match_mode}`);\nreturn [{\n  json: {\n    provider: 'asterisk',\n    phone: body.phone,\n    phone_digits: phoneDigits,\n    date: body.date || new Date().toISOString().slice(0, 10),\n    filename: body.filename || (uniqueid ? 'test-' + uniqueid + '.wav' : null),\n    uniqueid,\n    call_epoch: callEpoch,\n    country,\n    audio_bytes: buffer.length,\n    valid_audio: validAudio && phoneDigits.length >= 8,\n    duration_secs: secs === null ? 0 : secs,\n    duration_unknown: secs === null,\n    match_mode,\n    lookup_sql\n  },\n  binary: {\n    data: {\n      data: buffer.toString('base64'),\n      mimeType: 'audio/wav',\n      fileName: body.filename || 'recording.wav'\n    }\n  }\n}];\n"},"id":"728271df-86f3-494d-bcba-e9d8737a7a9d","name":"Convert Base64 to Binary","type":"n8n-nodes-base.code","typeVersion":2,"position":[20416,2160]},{"parameters":{"operation":"sendAudio","chatId":"={{ ({india: '-1004454561082', nepal: '-1004454561082', mexico: '-1003616406932'})[$json.country] || '-1003984044945' }}","binaryData":true,"additionalFields":{"caption":"=📞 {{ $json.phone }} — {{ ($json.country || 'unknown').toUpperCase() }} — {{ $json.date }} — {{ $json.duration_secs }}s"}},"id":"c07d6111-1771-4e8c-9df4-2d0290cef557","name":"Send to Telegram","type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[23328,2032],"webhookId":"telegram-send","credentials":{"telegramApi":{"id":"aZWABzEfC4SEy3oC","name":"Telegram account"}}},{"parameters":{"jsCode":"// ============================================================================\n// Telegram recibe SOLO grabaciones ya subidas al CRM (PUT confirmado) y de >= 60 s,\n// y sólo si ESTA ejecución fue la que marcó recording_synced 0->1 (así una subida\n// duplicada por dos ejecuciones simultáneas no manda el audio dos veces).\n// El CRM recibe todas las contestadas, sin importar la duración.\n// ============================================================================\nlet items = [];\ntry { items = $('🧾 Evaluar PUT (Asterisk)').all(); } catch (e) { items = []; }\nlet flipped = new Set();\ntry { flipped = new Set($('💾 Mark Recording Synced (Asterisk)').all().map(i => i.json && i.json.followup_id).filter(Boolean)); } catch (e) { flipped = new Set(); }\nreturn items\n  .filter(it => it.json && it.json.uploaded === true && it.binary && it.binary.data && flipped.has(it.json.followup_id))\n  .filter(it => it.json.suppress_telegram !== true && it.json.duration_unknown !== true && Number(it.json.duration_secs || 0) >= 60)\n  .map(it => {\n    const phone = String(it.json.phone_digits || it.json.phone || '').replace(/[^0-9]/g, '');\n    const secs = Number(it.json.duration_secs || 0);\n    const date = String(it.json.date || new Date().toISOString().slice(0, 10));\n    return {\n      json: Object.assign({}, it.json, { phone, country: it.json.country || 'unknown', date, duration_secs: secs }),\n      // se clona el binary sólo para cambiar el nombre visible en Telegram\n      binary: { data: Object.assign({}, it.binary.data, { fileName: `${phone}_${date}_${secs}s.wav` }) }\n    };\n  });\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[23104,1920],"id":"723334f5-9de1-440d-9a97-99720df345ef","name":"Code in JavaScript"},{"parameters":{"operation":"sendAudio","chatId":"={{ ({india: '-1003984044945', nepal: '-1003984044945', mexico: '-1003616406932'})[$json.country] || '-1003984044945' }}","binaryData":true,"additionalFields":{"caption":"=📞 {{ $json.phone }} — {{ ($json.country || 'unknown').toUpperCase() }} — {{ $json.date }} — {{ $json.duration_secs }}s"}},"id":"660cd707-3560-4824-a0a6-a9e3be226166","name":"Send to Telegram7","type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[23328,1840],"webhookId":"telegram-send","credentials":{"telegramApi":{"id":"aZWABzEfC4SEy3oC","name":"Telegram account"}}},{"parameters":{"rule":{"interval":[{"field":"minutes"}]}},"type":"n8n-nodes-base.scheduleTrigger","typeVersion":1.3,"position":[19728,2848],"id":"e3a442d7-16c1-4e2c-b64f-bcb090d884a6","name":"⏰ Schedule Stringee Recordings"},{"parameters":{"jsCode":"// Literal SQL seguro para el nodo MySQL de n8n (sin saltos de línea, sin \"$\", sin \"{{\").\nfunction q(v) {\n  if (v === null || v === undefined) return 'NULL';\n  if (typeof v === 'number') return Number.isFinite(v) ? String(Math.trunc(v)) : 'NULL';\n  return \"'\" + String(v).replace(/\\u0000/g, '').replace(/[\\r\\n]+/g, ' ').replace(/\\$/g, '')\n    .replace(/\\\\/g, '\\\\\\\\').replace(/'/g, \"''\").replace(/\\{\\{/g, '{ {').replace(/\\}\\}/g, '} }') + \"'\";\n}\n// \"followup_id|lead_id|synced|created_epoch|call_status|outcome\" -> objeto\nfunction parseOwner(s) {\n  if (!s) return null;\n  const p = String(s).split('|');\n  if (p.length < 4 || !p[0]) return null;\n  return { followup_id: p[0], lead_id: p[1] || null, synced: Number(p[2]) === 1 ? 1 : 0, created_epoch: Number(p[3]) || null, call_status: p[4] || null, outcome: p[5] || null };\n}\n// Duración desde el header WAV (sólo informativo: CRM no filtra por duración)\nfunction wavSecs(buf) {\n  try {\n    if (buf.length < 44 || buf.toString('ascii', 0, 4) !== 'RIFF') return null;\n    const byteRate = buf.readUInt32LE(28);\n    if (!byteRate) return null;\n    return Math.round(Math.max(0, buf.length - 44) / byteRate);\n  } catch (e) { return null; }\n}\nfunction countryOf(digits) {\n  if (digits.startsWith('977')) return 'nepal';\n  if (digits.startsWith('91')) return 'india';\n  if (digits.startsWith('58')) return 'venezuela';\n  if (digits.startsWith('52')) return 'mexico';\n  if (digits.startsWith('57')) return 'colombia';\n  return 'unknown';\n}\n// Condición común: filas válidas de wf_call_followups (excluye las históricas 'undefined')\n// (sin el carácter dólar: dentro del nodo MySQL, n8n arma la query con String.replace y un dólar seguido de\n// comilla se interpreta como patrón de reemplazo, corrompiendo el SQL)\nconst FCF_OK = \"CHAR_LENGTH(f.followup_id) = 36 AND f.followup_id REGEXP '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}' AND f.phone <> 'undefined' AND f.lead_id <> 'undefined'\";\n// Si el nodo MySQL anterior devolvió un error como item, se corta la ejecución (nunca se sigue \"a ciegas\")\nfunction assertNoDbError(items, where) {\n  const bad = items.filter(i => i && i.json && (i.json.error || (i.json.message && i.json.filename === undefined && i.json.owner === undefined)));\n  if (bad.length) throw new Error('Error de MySQL en ' + where + ': ' + String(bad[0].json.message || JSON.stringify(bad[0].json.error)).slice(0, 300));\n}\n\n// ============================================================================\n// 🔄 Fetch & Convert Stringee Recordings — PASO 1: sólo LISTA (no descarga audio).\n// - Alcance: grabaciones de las últimas MAX_AGE_HOURS (72 h rodantes, sin el corte de\n//   medianoche UTC del WF10 anterior: antes, lo no subido antes de 00:00 UTC se perdía).\n// - SIN BACKFILL al publicar: el primer ciclo del WF10 nuevo guarda su hora (static data)\n//   y nunca se toman grabaciones de más de 30 min antes de esa hora.\n//   Backlog anterior SÓLO con aprobación: BACKLOG_FROM = '2026-09-20T00:00:00Z' (máx. 10 días).\n//   PREFLIGHT sección 9 muestra cuántas se subirían.\n// - Excluye las ya registradas en el ledger (= subidas con PUT confirmado).\n// - Arma UNA consulta que busca, para cada grabación, su followup DUEÑO:\n//   la PRIMERA fila provider='stringee' del mismo teléfono creada entre 2 min\n//   antes y 90 min después del timestamp de la grabación. WF9 crea esa fila al\n//   cerrar el job de ESA llamada; la siguiente llamada al mismo lead no ocurre\n//   hasta que ese job se resolvió (y por el ciclo 3x3, >= 2 h después).\n// El audio se descarga recién en \"🧮 Decidir y Descargar\", sólo para las que se suben.\n// ============================================================================\nconst MAX_AGE_HOURS = 72;\nconst BACKLOG_FROM = '';   // '' = sin backfill. Con aprobación: fecha ISO desde la que se sube el backlog (máx. 10 días)\nconst ledger = new Set($input.all().map(i => i.json && i.json.filename).filter(Boolean));\nconst errs = $input.all().filter(i => i.json && (i.json.error || i.json.message) && !i.json.filename);\nif (errs.length) throw new Error('No se pudo leer el ledger wf10_sent_recordings: se omite el ciclo para no reprocesar todo');\n\nconst listData = await this.helpers.httpRequest({ method: 'GET', url: 'http://172.18.0.1:8091/recordings', json: true, timeout: 20000 });\nconst files = (listData && listData.recordings) || [];\nconst now = Date.now();\nconst sd = $getWorkflowStaticData('global');\nif (!sd.wf10_first_run_ms) sd.wf10_first_run_ms = now;          // primer ciclo del WF10 nuevo (se guarda sólo en ejecuciones reales)\nconst backlogMs = BACKLOG_FROM ? Date.parse(BACKLOG_FROM) : NaN;\nconst floorMs = Number.isFinite(backlogMs)\n  ? Math.max(now - 240 * 3600e3, backlogMs)\n  : Math.max(now - MAX_AGE_HOURS * 3600e3, sd.wf10_first_run_ms - 30 * 60e3);\nconst cand = [];\nlet inLedger = 0, tooOld = 0, empty = 0, badName = 0;\nfor (const r of files) {\n  const fn = String(r.filename || '');\n  const m = fn.match(/^stringee-(\\d{8,15})-(\\d{12,14})\\.wav$/);\n  if (!m) { badName++; continue; }\n  if (ledger.has(fn)) { inLedger++; continue; }\n  const tMs = Number(m[2]);\n  if (tMs < floorMs) { tooOld++; continue; }\n  if (Number(r.size_bytes) <= 44) { empty++; continue; }\n  cand.push({ filename: fn, phone_digits: m[1], t_ms: tMs, size_bytes: Number(r.size_bytes) || 0 });\n}\ncand.sort((a, b) => a.t_ms - b.t_ms); // las más viejas primero\nconsole.log(`WF10 Stringee: ${files.length} en worker | pendientes=${cand.length} | en ledger=${inLedger} | anteriores a ${new Date(floorMs).toISOString()} (sin backfill)=${tooOld} | vacías=${empty} | nombre inválido=${badName}`);\nif (!cand.length) return [];\n\nconst rows = cand.map(c => 'SELECT ' + q(c.filename) + ' AS filename, ' + q(c.phone_digits.slice(-10)) + ' AS p10, ' + q(Math.floor(c.t_ms / 1000)) + ' AS t_s').join(' UNION ALL ');\nconst lookup_sql = \"SELECT r.filename, (SELECT CONCAT_WS('|', f.followup_id, f.lead_id, COALESCE(f.recording_synced,0), UNIX_TIMESTAMP(f.created_at), COALESCE(f.call_status,''), COALESCE(f.outcome,'')) \" +\n  \"FROM wf_call_followups f WHERE f.provider = 'stringee' AND \" + FCF_OK + \" AND RIGHT(f.phone,10) = r.p10 \" +\n  \"AND f.created_at >= FROM_UNIXTIME(r.t_s - 120) AND f.created_at <= FROM_UNIXTIME(r.t_s + 5400) \" +\n  \"ORDER BY f.created_at ASC, f.id ASC LIMIT 1) AS owner FROM (\" + rows + \") r\";\nreturn [{ json: { candidates: cand, lookup_sql } }];\n"},"id":"f0de754b-fb93-4a67-a325-422fd7aecdcd","name":"🔄 Fetch & Convert Stringee Recordings","type":"n8n-nodes-base.code","typeVersion":2,"position":[20320,2816]},{"parameters":{"jsCode":"// ============================================================================\n// Telegram recibe SOLO grabaciones ya subidas al CRM (PUT confirmado) y de >= 60 s,\n// y sólo si ESTA ejecución fue la que marcó recording_synced 0->1 (así una subida\n// duplicada por dos ejecuciones simultáneas no manda el audio dos veces).\n// El CRM recibe todas las contestadas, sin importar la duración.\n// ============================================================================\nlet items = [];\ntry { items = $('🧾 Evaluar PUT (Stringee)').all(); } catch (e) { items = []; }\nlet flipped = new Set();\ntry { flipped = new Set($('💾 Mark Recording Synced (Stringee)').all().map(i => i.json && i.json.followup_id).filter(Boolean)); } catch (e) { flipped = new Set(); }\nreturn items\n  .filter(it => it.json && it.json.uploaded === true && it.binary && it.binary.data && flipped.has(it.json.followup_id))\n  .filter(it => it.json.suppress_telegram !== true && it.json.duration_unknown !== true && Number(it.json.duration_secs || 0) >= 60)\n  .map(it => {\n    const phone = String(it.json.phone_digits || it.json.phone || '').replace(/[^0-9]/g, '');\n    const secs = Number(it.json.duration_secs || 0);\n    const date = String(it.json.date || new Date().toISOString().slice(0, 10));\n    return {\n      json: Object.assign({}, it.json, { phone, country: it.json.country || 'unknown', date, duration_secs: secs }),\n      // se clona el binary sólo para cambiar el nombre visible en Telegram\n      binary: { data: Object.assign({}, it.binary.data, { fileName: `${phone}_${date}_${secs}s.wav` }) }\n    };\n  });\n"},"type":"n8n-nodes-base.code","typeVersion":2,"position":[22784,2688],"id":"5fe37163-d1c4-4f76-8151-51f99f008182","name":"Code in JavaScript (Stringee)"},{"parameters":{"operation":"sendAudio","chatId":"={{ ({india: '-1004454561082', nepal: '-1004454561082', mexico: '-1003616406932'})[$json.country] || '-1003984044945' }}","binaryData":true,"additionalFields":{"caption":"=📞 STRINGEE {{ $json.phone }} — {{ ($json.country || 'unknown').toUpperCase() }} — {{ $json.date }} — {{ $json.duration_secs }}s"}},"id":"ad3f86ef-ee44-4b41-96de-27e202e8f165","name":"Send to Telegram (Stringee)","type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[23008,2784],"webhookId":"telegram-send-stringee-1","credentials":{"telegramApi":{"id":"aZWABzEfC4SEy3oC","name":"Telegram account"}}},{"parameters":{"operation":"sendAudio","chatId":"={{ ({india: '-1003984044945', nepal: '-1003984044945', mexico: '-1003616406932'})[$json.country] || '-1003984044945' }}","binaryData":true,"additionalFields":{"caption":"=📞 STRINGEE {{ $json.phone }} — {{ ($json.country || 'unknown').toUpperCase() }} — {{ $json.date }} — {{ $json.duration_secs }}s"}},"id":"dad32dfd-685c-40cf-b100-b0c0910325f9","name":"Send to Telegram1 (Stringee)","type":"n8n-nodes-base.telegram","typeVersion":1.2,"position":[23008,2592],"webhookId":"telegram-send-stringee-2","credentials":{"telegramApi":{"id":"aZWABzEfC4SEy3oC","name":"Telegram account"}}},{"parameters":{"operation":"executeQuery","query":"{{ $json.lookup_sql }}","options":{}},"id":"17f92529-45f7-4aed-8181-a15153cd111d","name":"🔍 Lookup Followup ID (Asterisk)","type":"n8n-nodes-base.mySql","typeVersion":2.4,"position":[20640,2160],"retryOnFail":true,"maxTries":2,"credentials":{"mySql":{"id":"4NiWyzzJ4JbMkIjT","name":"MySQL account"}}},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":2},"conditions":[{"id":"decision-attach","leftValue":"={{ $json.decision }}","rightValue":"attach","operator":{"type":"string","operation":"equals"}}],"combinator":"and"},"options":{}},"id":"2d341f74-6435-48c3-8c4f-e230cade0ec9","name":"🔀 Followup Encontrado? (Asterisk)","type":"n8n-nodes-base.if","typeVersion":2.2,"position":[21088,2160]},{"parameters":{"method":"POST","url":"http://172.18.0.1:8092/token","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"}]},"options":{"response":{"response":{"neverError":true,"responseFormat":"json"}},"timeout":15000}},"id":"24790e9a-8ad6-44f1-927b-48593b955c14","name":"🔐 Login LeadStudio (WF10-Asterisk)","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[21312,2000],"retryOnFail":false,"maxTries":2},{"parameters":{"mode":"runOnceForEachItem","jsCode":"// Literal SQL seguro para el nodo MySQL de n8n (sin saltos de línea, sin \"$\", sin \"{{\").\nfunction q(v) {\n  if (v === null || v === undefined) return 'NULL';\n  if (typeof v === 'number') return Number.isFinite(v) ? String(Math.trunc(v)) : 'NULL';\n  return \"'\" + String(v).replace(/\\u0000/g, '').replace(/[\\r\\n]+/g, ' ').replace(/\\$/g, '')\n    .replace(/\\\\/g, '\\\\\\\\').replace(/'/g, \"''\").replace(/\\{\\{/g, '{ {').replace(/\\}\\}/g, '} }') + \"'\";\n}\n// \"followup_id|lead_id|synced|created_epoch|call_status|outcome\" -> objeto\nfunction parseOwner(s) {\n  if (!s) return null;\n  const p = String(s).split('|');\n  if (p.length < 4 || !p[0]) return null;\n  return { followup_id: p[0], lead_id: p[1] || null, synced: Number(p[2]) === 1 ? 1 : 0, created_epoch: Number(p[3]) || null, call_status: p[4] || null, outcome: p[5] || null };\n}\n// Duración desde el header WAV (sólo informativo: CRM no filtra por duración)\nfunction wavSecs(buf) {\n  try {\n    if (buf.length < 44 || buf.toString('ascii', 0, 4) !== 'RIFF') return null;\n    const byteRate = buf.readUInt32LE(28);\n    if (!byteRate) return null;\n    return Math.round(Math.max(0, buf.length - 44) / byteRate);\n  } catch (e) { return null; }\n}\nfunction countryOf(digits) {\n  if (digits.startsWith('977')) return 'nepal';\n  if (digits.startsWith('91')) return 'india';\n  if (digits.startsWith('58')) return 'venezuela';\n  if (digits.startsWith('52')) return 'mexico';\n  if (digits.startsWith('57')) return 'colombia';\n  return 'unknown';\n}\n// Condición común: filas válidas de wf_call_followups (excluye las históricas 'undefined')\n// (sin el carácter dólar: dentro del nodo MySQL, n8n arma la query con String.replace y un dólar seguido de\n// comilla se interpreta como patrón de reemplazo, corrompiendo el SQL)\nconst FCF_OK = \"CHAR_LENGTH(f.followup_id) = 36 AND f.followup_id REGEXP '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}' AND f.phone <> 'undefined' AND f.lead_id <> 'undefined'\";\n// Si el nodo MySQL anterior devolvió un error como item, se corta la ejecución (nunca se sigue \"a ciegas\")\nfunction assertNoDbError(items, where) {\n  const bad = items.filter(i => i && i.json && (i.json.error || (i.json.message && i.json.filename === undefined && i.json.owner === undefined)));\n  if (bad.length) throw new Error('Error de MySQL en ' + where + ': ' + String(bad[0].json.message || JSON.stringify(bad[0].json.error)).slice(0, 300));\n}\n\n// ============================================================================\n// 🔗 Attach Audio + Token (Asterisk) — modo \"Run Once for Each Item\".\n// Token de ESTE item (Login) + decisión/followup de ESTE item + audio del MISMO\n// item por pairing (Convert Base64 to Binary). Si falta algo, falla (el webhook\n// responde 500 y el worker reintenta): nunca se hace PUT a un followup vacío.\n// ============================================================================\nconst token = $input.item.json.accessToken;\nconst dec = $('🧮 Decidir Match (Asterisk)').item.json;\nconst src = $('Convert Base64 to Binary').item;\nif (!token) throw new Error('Login LeadStudio sin accessToken');\nif (!dec || dec.decision !== 'attach' || !dec.followup_id) throw new Error('item sin followup_id / decisión attach');\nif (!src || !src.binary || !src.binary.data) throw new Error('item sin audio (binary.data)');\nreturn {\n  json: Object.assign({}, dec, { accessToken: token }),\n  binary: src.binary\n};\n"},"id":"214213ff-04d2-4ee3-9a18-99c7ece41c4c","name":"🔗 Attach Audio + Token (Asterisk)","type":"n8n-nodes-base.code","typeVersion":2,"position":[21536,2000]},{"parameters":{"method":"PUT","url":"={{ 'https://lead-studio-9gnl.onrender.com/api/calls/recording/' + $json.followup_id }}","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{ $json.accessToken }}"}]},"sendBody":true,"contentType":"multipart-form-data","bodyParameters":{"parameters":[{"parameterType":"formBinaryData","name":"file","inputDataFieldName":"data"}]},"options":{"response":{"response":{"fullResponse":true,"neverError":true,"responseFormat":"json"}},"timeout":60000}},"id":"98b6d146-c4b8-426d-9223-00f11740e79b","name":"📤 PUT Recording — LeadStudio (Asterisk)","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[21760,2000],"retryOnFail":false,"maxTries":2,"onError":"continueRegularOutput"},{"parameters":{"operation":"executeQuery","query":"{{ $json.mark_sql }}",